      "speaker": "bot",
      "text": "Hello आपको Roland XPS 10 motherboard की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ हाँ।"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "आप जिस seller को call कर रहे थे।"
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "जी बिल्कुल मिल जाएगा।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "पूरा"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "तो क्या करेगा?"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "मैं आपको दूसरे अच्छे sellers से connect करने में मदद करूंगी।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "चलिए पहले कुछ details confirm कर लेते हैं।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "बताइए brand में क्या आप prefer करेंगे HP, Dell या कोई और?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "आता सब brand।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "पर क्या आप किसी खास brand का नाम बता सकते हैं जैसे HP, Dell या कोई और?"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "मैं HP का।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "अब बताइए कि आप इनमें से क्या पसंद करेंगे?"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "Dell motherboard, HP motherboard या कुछ और?"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "एक ही mother word।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "ठीक है अब आगे बढ़ते हैं।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "ठीक है आप अपनी city और state भी बता दीजिए please।"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "क्या?"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "माफ़ कीजिए मैं पूछ रही थी कि आप अपनी city और state बता दीजिए please."
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "बालीगुड़ा बालीगुड़ा कंदमाड़ मैं आपकी city और state पूछ रही थी।"
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "Please बता दीजिए आप कहाँ से बोल रहे हैं?"
    },
    {
      "i": 24,
      "speaker": "caller",
      "text": "बल्लीगुड़ा बल्लीगुड़ा को।"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "क्षमा करें मुझे समझ नहीं आया।"
    },
    {
      "i": 26,
      "speaker": "bot",
      "text": "क्या आप अपनी city और state बता सकते हैं?"
    },
    {
      "i": 27,
      "speaker": "caller",
      "text": "कंदमाल कंदमाल।"
    },
    {
      "i": 28,
      "speaker": "bot",
      "text": "मैं आपकी city और state पूछ रही हूं ताकि सही seller से connect कर सकूं।"
    },
    {
      "i": 29,
      "speaker": "bot",
      "text": "Please बता दीजिए।"
    }
  ]
}
